CREATE TABLE producto (id INTEGER PRIMARY KEY, sku TEXT UNIQUE, nombre TEXT, costo REAL);
CREATE TABLE cuenta (codigo TEXT PRIMARY KEY, nombre TEXT, tipo TEXT);
CREATE TABLE asiento (id INTEGER PRIMARY KEY, fecha TEXT, origen TEXT);
CREATE TABLE asiento_linea (
  asiento_id INTEGER REFERENCES asiento(id),
  cuenta     TEXT    REFERENCES cuenta(codigo),
  debe  REAL NOT NULL DEFAULT 0,
  haber REAL NOT NULL DEFAULT 0,
  CHECK (debe >= 0 AND haber >= 0 AND (debe = 0 OR haber = 0)));
CREATE TABLE mov_stock (id INTEGER PRIMARY KEY,
  producto_id INTEGER REFERENCES producto(id),
  cantidad INTEGER, origen TEXT,
  asiento_id INTEGER REFERENCES asiento(id));
